PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?deathDate WHERE {
  VALUES ?person { dbr:Joseph_Dudley dbr:Francisco_Herrera_Luque }
  OPTIONAL { ?person dbp:deathDate ?dbpDeath . }
  OPTIONAL { ?person dbo:deathDate ?dboDeath . }
  BIND (COALESCE(?dbpDeath, ?dboDeath) AS ?deathDate)
}
LIMIT 100

